import {readFileSync,readdirSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {handleOperationsApi} from '../src/api/operations-api.mjs';
import {DEMO_CLIENT} from '../src/admin/demo-client.mjs';
import {previewObservations,commitObservations,aggregateObservations} from '../src/platform/operations/observations.mjs';
import {ADVISER_METRICS} from '../src/platform/operations/adviser-contract.mjs';
import {BACKUP_TABLES,BACKUP_SCHEMA_VERSION,createBackupSnapshot,backupToSql} from '../src/api/backup.mjs';

const VIEWS=['overview','map','shop','trade','delivery','team','visitors','market','products','keywords','traffic','profiles','ai','advertising','guide','dictionary'];
const ORIGIN='https://adviser.synthetic.test';
const owner={id:'owner',name:'Synthetic owner',role:'owner'};
const manager={id:'manager-review',name:'Synthetic manager',role:'manager'};
const sales={id:'sales-review',name:'Synthetic sales',role:'sales'};
const viewer={id:'viewer-review',name:'Synthetic viewer',role:'viewer'};
const failures=[],results=[],networkAttempts=[];
let passed=0;
const priorFetch=globalThis.fetch;
globalThis.fetch=async(...args)=>{networkAttempts.push(String(args[0]));throw Error('Network is forbidden in adviser integration tests.');};

async function test(name,fn){try{const details=await fn();passed++;results.push({name,passed:true,...(details||{})});}catch(error){failures.push({name,error:error.message,stack:String(error.stack||'').slice(0,1800)});results.push({name,passed:false,error:error.message});}}
const sha256=value=>createHash('sha256').update(value).digest('hex');
function csvCell(value){const text=String(value??'');return /[",\r\n]/.test(text)?'"'+text.replaceAll('"','""')+'"':text;}
const COLUMNS=['date','date_to','metric','value_exact','numerator','denominator','unit','currency','series','device','country','product','keyword','channel','industry'];
function metricCsv(rows,columns=COLUMNS){return columns.join(',')+'\n'+rows.map(row=>columns.map(key=>csvCell(row[key]??'')).join(',')).join('\n');}

function database(){
 const sqlite=new DatabaseSync(':memory:');sqlite.exec('PRAGMA foreign_keys=ON');
 const migrations=readdirSync(new URL('../migrations/',import.meta.url)).filter(name=>/^\d{4}_.+\.sql$/.test(name)).sort();
 for(const name of migrations)sqlite.exec(readFileSync(new URL('../migrations/'+name,import.meta.url),'utf8'));
 let calls=0,statements=0,returnedRows=0,beforeBatch=null;
 const runStatement=(sql,values)=>{statements++;const stmt=sqlite.prepare(sql);if(stmt.columns().length){const data=stmt.all(...values);returnedRows+=data.length;return {success:true,results:data,meta:{changes:Number(sqlite.prepare('SELECT changes() n').get().n)}};}const info=stmt.run(...values);return{success:true,results:[],meta:{changes:Number(info.changes)}};};
 const db={prepare(sql){return{sql,values:[],bind(...values){assert.ok(values.length<=100,'D1 bound-parameter limit exceeded.');this.values=values;return this;},async first(column){calls++;const result=runStatement(sql,this.values).results[0]||null;return column&&result?result[column]:result;},async all(){calls++;return runStatement(sql,this.values);},async run(){calls++;return runStatement(sql,this.values);}};},async batch(items){calls++;if(beforeBatch){const hook=beforeBatch;beforeBatch=null;await hook(items);}sqlite.exec('BEGIN IMMEDIATE');try{const result=items.map(item=>runStatement(item.sql,item.values));sqlite.exec('COMMIT');return result;}catch(error){sqlite.exec('ROLLBACK');throw error;}}};
 function insert(table,value){assert.match(table,/^[a-z_]+$/);const keys=Object.keys(value);sqlite.prepare('INSERT INTO '+table+' ('+keys.join(',')+') VALUES ('+keys.map(()=>'?').join(',')+')').run(...keys.map(key=>value[key]));}
 function trace(){return{d1_calls:calls,sql_statements:statements,returned_rows:returnedRows};}
 function resetTrace(){calls=0;statements=0;returnedRows=0;}
 return{sqlite,db,insert,trace,resetTrace,beforeNextBatch(fn){beforeBatch=fn;},close(){sqlite.close();}};
}
function harness({timezone='Asia/Singapore'}={}){
 const store=database(),env={DB:store.db,ADMIN_TIMEZONE:timezone};
 async function api(path,{method='GET',body,actor=owner,origin=ORIGIN,headers={}}={}){
  const request=new Request(ORIGIN+'/admin/api/operations/'+path,{method,headers:{origin,...(body===undefined?{}:{'content-type':'application/json'}),...headers},...(body===undefined?{}:{body:typeof body==='string'?body:JSON.stringify(body)})});
  store.resetTrace();const response=await handleOperationsApi(request,env,actor,new URL(request.url));
  if(!response)return{status:0,response:null,trace:store.trace(),data:undefined,value:undefined};
  const value=(response.headers.get('content-type')||'').includes('application/json')?await response.json():await response.text();
  return{status:response.status,response,value,data:value?.data,trace:store.trace()};
 }
 return{...store,env,api};
}
function ok(result,status=200){assert.equal(result.status,status,JSON.stringify(result.value));assert.ok(result.trace.d1_calls<=50,'D1 Free invocation limit exceeded: '+JSON.stringify(result.trace));return result.data;}
async function createSource(h,kind='csv_generic',name='Independent synthetic metrics'){return ok(await h.api('sources',{method:'POST',body:{kind,name}}),201);}
async function commitMetrics(h,source,csv){const preview=await h.api('adviser/preview',{method:'POST',body:{source_id:source.id,csv}});ok(preview);const digest=preview.data.sha256||sha256(csv);const committed=await h.api('adviser/commit',{method:'POST',body:{source_id:source.id,csv,sha256:digest}});ok(committed);return{preview,committed};}
const query=values=>new URLSearchParams(Object.entries(values).filter(([,value])=>value!==undefined).map(([key,value])=>[key,String(value)])).toString();

