await test('profile country and email charts, table, scoped export and every slice reconcile to the same customer records',async()=>{
 const h=harness();try{commerceFixture(h);const at='2026-11-01T00:00:00.000Z';for(const[id,external_id,country,email]of [['PROFILE-DE','BUYER-A','DE','known@synthetic.test'],['PROFILE-US','BUYER-B','US',''],['PROFILE-MISSING','OTHER','','']])h.insert('ops_commerce_customers',{id,source_id:'source-a',external_id,name:'Synthetic business',country,email,source_created_at:at,created_at:at,updated_at:at});
 const check=async(packet,total)=>{assert.equal(measured(packet,'customer_records').value_exact,String(total));const country=packet.charts.find(chart=>chart.id==='customer-country-distribution'),email=packet.charts.find(chart=>chart.id==='customer-data-completeness');assert.ok(country);assert.ok(email);for(const chart of [country,email]){assert.equal(chart.series[0].points.reduce((sum,point)=>sum+BigInt(point.value_exact),0n),BigInt(total));for(const point of chart.series[0].points){if(!point.drill){assert.equal(point.value_exact,'0','Only a zero unavailable slice may omit drill.');continue;}const scope=Object.fromEntries(Object.entries(point.drill).filter(([key])=>key!=='timeZone'));const detail=ok(await h.api('adviser/drill?'+query(scope)));assert.equal(String(detail.meta.total),point.value_exact,JSON.stringify({scope,point:point.x}));if(point.drill.profile_email==='present')assert.ok(detail.rows.every(row=>row.external_id==='BUYER-A'));if(point.drill.profile_email==='missing')assert.ok(detail.rows.every(row=>['BUYER-B','OTHER'].includes(row.external_id)));if(point.drill.country==='__missing__')assert.ok(detail.rows.every(row=>row.country===null||row.country===''));}}
 assert.equal(packet.table.rows.reduce((sum,row)=>sum+row.customer_records,0),total);for(const row of packet.table.rows)assert.equal(row.profile_email_recorded+row.profile_missing_email,row.customer_records);return{country,email};};
 const all=await adviser(h,{view:'profiles',source_id:'source-a'}),charts=await check(all,3);assert.equal(measured(all,'profile_missing_email').value_exact,'2');assert.ok(charts.country.series[0].points.some(point=>point.drill.country==='__missing__'));assert.equal(charts.email.series[0].points.find(point=>point.drill.profile_email==='present').value_exact,'1');assert.equal(charts.email.series[0].points.find(point=>point.drill.profile_email==='missing').value_exact,'2');
 const metric=measured(all,'customer_records'),scope=Object.fromEntries(Object.entries(metric.drill).filter(([key])=>key!=='timeZone'));const exported=await h.api('adviser/export.csv?'+query(scope));assert.equal(exported.status,200);assert.equal(exported.value.trim().split(/\r?\n/).length,4);assert.ok(exported.value.includes('BUYER-A'));assert.ok(exported.value.includes('BUYER-B'));assert.ok(exported.value.includes('OTHER'));
 const filtered=await adviser(h,{view:'profiles',source_id:'source-a',product:'CAM-B',currency:'USD'});await check(filtered,1);assert.equal(measured(filtered,'profile_missing_email').value_exact,'0');const missing=await adviser(h,{view:'profiles',source_id:'source-a',profile_email:'missing'});await check(missing,2);assert.equal(measured(missing,'repeat_order_customers').value_exact,'0');assert.equal(measured(missing,'contact_addresses').value_exact,null);assert.equal((await h.api('adviser?'+query({view:'profiles',profile_email:'arbitrary'}))).status,422);
 }finally{h.close();}
});
